def chain_follower(chain):
    tokens = list(chain)
    tokens.sort()
    result = []
    for i in range(len(tokens) - 1):
        first = tokens[i]
        second = tokens[i + 1]
        if first == second:
            result.append(first)
        else:
            result.append(second)
    return ','.join(result)

